 33	
 34	public final class PostgresStore implements Store {
 35	    private static final ObjectMapper JSON = new ObjectMapper();
 36	
 37	    private final DataSource dataSource;
 38	
 39	    public PostgresStore(DataSource dataSource) {
 40	        this.dataSource = dataSource;
 41	    }
 42	
 43	    @Override
 44	    public <T> T inTransaction(Function<Tx, T> work) {
 45	        try (Connection connection = dataSource.getConnection()) {
 46	            connection.setAutoCommit(false);
 47	            try {
 48	                T result = work.apply(new PostgresTx(connection));
 49	                connection.commit();
 50	                return result;
 51	            } catch (Throwable e) {
 52	                connection.rollback();
 53	                throw e;
 54	            }
 55	        } catch (SQLException e) {
 56	            throw new IllegalStateException(e);
 57	        }
 58	    }
 59	
 60	    private static final class PostgresTx implements Tx {
 61	        private final Connection connection;
 62	
 63	        PostgresTx(Connection connection) {
 64	            this.connection = connection;
 65	        }
 66	
 67	        @Override
 68	        public ProductRepository products() {
 69	            return new Products(connection);
 70	        }
 71	
 72	        @Override
 73	        public OrderRepository orders() {
 74	            return new Orders(connection);
 75	        }
 76	
 77	        @Override
 78	        public CustomerRepository customers() {
 79	            return new Customers(connection);
 80	        }
 81	
 82	        @Override
 83	        public NotificationRepository notifications() {
 84	            return new Notifications(connection);
 85	        }
 86	
 87	        @Override
 88	        public PaymentNoticeRepository paymentNotices() {
 89	            return new PaymentNotices(connection);
 90	        }
 91	    }
 92	
 93	    private interface Binder {
 94	        void bind(PreparedStatement statement) throws SQLException;
 95	    }
 96	
 97	    private interface RowReader<T> {
 98	        T read(ResultSet row) throws SQLException;
 99	    }
100	
101	    private static void update(Connection connection, String sql, Binder binder) {
102	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
103	            binder.bind(statement);
104	            statement.executeUpdate();
